/** The centre panel entry. */
/** How many times the panel body has rendered; a probe can read it. */
let idePanelRenders = 0

function IdePanel({ store, translate, onBackToChat, onToggleSidebar, onEnter, useSessions, useWorkspaces, navigate, paletteActions }) {
  const tr = typeof translate === 'function' ? translate : (key) => key
  const actions = paletteActions ?? []

  // IDEA's gesture: two Shift presses in quick succession open Search Everywhere.
  // The key and the window come from the shortcut registry, not from here.
  const sequence = IDE_SHORTCUTS.find((entry) => entry.action === 'palette')?.sequence
    ?? { key: 'Shift', repeat: 2, windowMs: 400 }
  useEffect(() => {
    const DOUBLE_SHIFT_MS = sequence.windowMs
    let lastShift = 0
    const onKey = (event) => {
      if (event.key !== sequence.key || event.repeat === true) return
      const now = Date.now()
      if (lastShift !== 0 && now - lastShift <= DOUBLE_SHIFT_MS) {
        lastShift = 0
        store.setPaletteOpen(true)
        return
      }
      lastShift = now
    }
    globalThis.addEventListener('keyup', onKey)
    return () => globalThis.removeEventListener('keyup', onKey)
  }, [store])
  // Coming back to the window re-reads the active file: a commit changes git's
  // view of it without changing its bytes, so no change frame arrives.
  useEffect(() => {
    const onFocus = () => {
      store.reloadActive?.()
      void store.refreshVcs?.()
    }
    globalThis.addEventListener('focus', onFocus)
    return () => globalThis.removeEventListener('focus', onFocus)
  }, [store])

  // The setup guide: one check when the workspace is entered, then on demand.
  const [setupOpen, setSetupOpen] = useState(false)
  const [setupBusy, setSetupBusy] = useState(false)
  const [setupStill, setSetupStill] = useState(false)
  useEffect(() => {
    let cancelled = false
    void ideDoctorQuery().then((found) => {
      if (found.ok === true && found.mavenRepo !== '') store.setMavenRepoDetected(found.mavenRepo, found.mavenRepoExists === true)
      if (cancelled || found.ok !== true || found.lsp === true) return
      if (!ideSetupDismissed) setSetupOpen(true)
    })
    return () => { cancelled = true }
  }, [])
  const checkSetup = () => {
    setSetupBusy(true)
    setSetupStill(false)
    void ideDoctorQuery().then((found) => {
      setSetupBusy(false)
      if (found.ok === true && found.lsp === true) {
        setSetupOpen(false)
        store.setNotice(tr('setupReady'))
        return
      }
      setSetupOpen(true)
      setSetupStill(true)
    })
  }
  const closeSetup = () => {
    ideSetupDismissed = true
    setSetupOpen(false)
  }

  idePanelRenders += 1
  const state = useSyncExternalStore(store.subscribe, store.getState, store.getState)
  const tab = state.tabs.find((entry) => entry.path === state.activePath)

  // Second resolver: the panel asks the same two snapshots the tracker uses, so
  // a tracker that missed its pass cannot leave the panel blank. Both writers
  // compute the same values from the same sources, so they cannot disagree.
  const selectSessions = typeof useSessions === 'function' ? useSessions : () => undefined
  const selectWorkspaces = typeof useWorkspaces === 'function' ? useWorkspaces : () => undefined
  const sessions = selectSessions((snapshot) => snapshot)
  const workspaces = selectWorkspaces((snapshot) => snapshot)
  const resolved = ideResolveTarget(undefined, sessions, workspaces)

  // Every workspace the shell knows about, plus the Session-derived root, which
  // may not belong to a registered workspace yet.
  const projects = []
  const seenPaths = new Set()
  for (const item of Array.isArray(workspaces?.items) ? workspaces.items : []) {
    const path = typeof item?.path === 'string' ? item.path.replace(/\/+$/, '') : ''
    if (path === '' || seenPaths.has(path)) continue
    seenPaths.add(path)
    projects.push({ path, title: typeof item?.title === 'string' && item.title !== '' ? item.title : ideBasename(path) })
  }
  const resolvedRoot = typeof resolved.root === 'string' ? resolved.root.replace(/\/+$/, '') : ''
  if (resolvedRoot !== '' && !seenPaths.has(resolvedRoot)) {
    projects.unshift({ path: resolvedRoot, title: ideBasename(resolvedRoot) })
  }

  const workspaceItems = Array.isArray(workspaces?.items) ? workspaces.items : []
  const sessionOfProject = (path) => {
    if (path === '') return undefined
    const item = workspaceItems.find((entry) => typeof entry?.path === 'string'
      && entry.path.replace(/\/+$/, '') === path)
    const ids = Array.isArray(item?.sessionIds) ? item.sessionIds : []
    return typeof ids[0] === 'string' ? ids[0] : undefined
  }

  // The Session decides which workspace the panel shows. Opening the panel from
  // a conversation therefore lands in that conversation's project, every time.
  // A root change is applied with its Session in one patch: doing it in two
  // steps reloaded the old tabs out of scope and flashed a red error. The
  // current root is read, not subscribed: a manual project switch must not be
  // reverted by this effect re-running on its own patch.
  useEffect(() => {
    if (typeof resolved.sessionId === 'string') {
      if (resolvedRoot !== '' && store.getState().rootPath !== resolvedRoot) {
        store.enterProject(resolvedRoot, resolved.sessionId)
        return
      }
      store.rememberSession(resolved.sessionId)
      return
    }
    if (resolvedRoot !== '') store.setRoot(resolvedRoot)
  }, [resolved.sessionId, resolvedRoot, store])

  /** Switch projects: adopt a Session of that workspace first, then re-root. */
  const selectProject = (path) => {
    const sessionId = sessionOfProject(path)
    if (sessionId === undefined) {
      store.setNotice(tr('projectNoSession'))
      return
    }
    store.enterProject(path, sessionId)
  }

  // Mouse side buttons are the usual back/forward gesture; Chromium would take
  // them as history navigation, so both edges are claimed for the code history.
  useEffect(() => {
    // Only `auxclick` performs the step. `mousedown`/`mouseup` merely suppress
    // the browser's own history navigation, otherwise one press would walk the
    // history three times.
    const isSideButton = (event) => event.button === 3 || event.button === 4
    const suppress = (event) => {
      if (!isSideButton(event)) return
      event.preventDefault()
      event.stopPropagation()
    }
    const onAuxClick = (event) => {
      if (!isSideButton(event)) return
      event.preventDefault()
      event.stopPropagation()
      if (event.button === 3) store.goBack()
      else store.goForward()
    }
    globalThis.addEventListener('mousedown', suppress, true)
    globalThis.addEventListener('mouseup', suppress, true)
    globalThis.addEventListener('auxclick', onAuxClick, true)
    return () => {
      globalThis.removeEventListener('mousedown', suppress, true)
      globalThis.removeEventListener('mouseup', suppress, true)
      globalThis.removeEventListener('auxclick', onAuxClick, true)
    }
  }, [store])

  // Coming back to the window is a reliable moment to re-read open files: an
  // external editor may have saved while this page was in the background.
  useEffect(() => {
    let timer
    const refreshSoon = () => {
      if (timer !== undefined) clearTimeout(timer)
      timer = setTimeout(() => { timer = undefined; store.refreshTabs() }, 200)
    }
    const onVisible = () => { if (document.visibilityState === 'visible') refreshSoon() }
    globalThis.addEventListener('focus', refreshSoon)
    document.addEventListener('visibilitychange', onVisible)
    return () => {
      if (timer !== undefined) clearTimeout(timer)
      globalThis.removeEventListener('focus', refreshSoon)
      document.removeEventListener('visibilitychange', onVisible)
    }
  }, [store])

  // Selecting this panel is what starts the mode: the navigation column folds
  // away and the conversation floats over the panel. Unmounting reverses both.
  useEffect(() => {
    if (typeof onEnter !== 'function') return undefined
    return onEnter()
  }, [onEnter])

  const missing = state.sessionId === null
    ? `session=${state.sessionId === null ? 'none' : state.sessionId} root=${state.rootPath === '' ? 'none' : state.rootPath} remote=${state.remoteReady === true ? 'ready' : 'waiting'}`
    : undefined

  let content
  if (state.sessionId === null || state.rootPath === '') {
    content = h('div', { className: 'iw-empty' }, [
      h('div', { key: 't', className: 'iw-empty-title' }, tr('noWorkspace')),
      h('div', { key: 'h' }, tr('noWorkspaceHint')),
      h('button', {
        key: 'retry',
        type: 'button',
        className: 'iw-btn primary',
        onClick: () => store.retryResolve(),
      }, tr('reload')),
      h('div', {
        key: 'diag',
        style: { marginTop: '10px', fontSize: '11px', opacity: 0.65, fontFamily: 'ui-monospace, monospace' },
      }, missing ?? ''),
    ])
  } else if (tab === undefined) {
    content = h(IdeEmptyEditor, { key: 'empty', tr })
  } else if (tab.status === 'error') {
    content = h('div', { className: 'iw-empty' }, [
      h('div', { key: 't', className: 'iw-empty-title' }, tr('fileNotText')),
      h('div', { key: 'e' }, `${tr('errorPrefix')}${tab.error}`),
      h('button', {
        key: 'r',
        type: 'button',
        className: 'iw-btn primary',
        onClick: () => store.openFile(tab.path),
      }, tr('reload')),
    ])
  } else {
    content = h(IdeCodeView, { key: `code:${tab.path}`, tab, tr, store, navigate })
  }

  const banner = state.liveNotice === ''
    ? null
    : h('div', { key: 'banner', className: 'iw-banner' }, state.liveNotice)

  const codeSize = Number.isFinite(state.codeFontSize) ? state.codeFontSize : 12.5
  const treeSize = Number.isFinite(state.treeFontSize) ? state.treeFontSize : 14.5
  return h('div', {
    className: 'iw-root',
    // The editor and the tree share one typographic scale, set in Settings.
    style: {
      '--iw-code-font-size': `${codeSize}px`,
      '--iw-code-line-height': `${Math.round(codeSize * 1.6)}px`,
      '--iw-tree-font-size': `${treeSize}px`,
      '--iw-row-height': `${Math.round(treeSize * 1.86)}px`,
    },
  }, [
    h(IdeStyles, { key: 'style' }),
    h(IdeToolbar, { key: 'toolbar', store, state, tr, projects, onSelectProject: selectProject, onToggleSidebar }),
    banner,
    h(IdeTreeMenu, {
      key: 'treemenu',
      store,
      state,
      tr,
    }),
    h(IdeTreePopup, {
      key: 'treepopup',
      store,
      state,
      tr,
    }),
    h(IdeGutterMenu, {
      key: 'guttermenu',
      store,
      state,
      tr,
    }),
    h(IdeTabMenu, {
      key: 'tabmenu',
      store,
      state,
      tr,
      copy: (text) => {
        const clip = globalThis.navigator?.clipboard
        if (clip !== undefined && typeof clip.writeText === 'function') {
          void clip.writeText(text).catch(() => undefined)
        }
        store.setNotice(`${tr('tabMenuCopied')}: ${text}`)
      },
    }),
    h(IdeSetupDialog, {
      key: 'setup',
      tr,
      open: setupOpen,
      busy: setupBusy,
      still: setupStill,
      onCheck: checkSetup,
      onClose: closeSetup,
    }),
    h('div', { key: 'body', className: 'iw-body' }, [
      state.treeVisible ? h(IdeTree, { key: 'tree', store, state, tr }) : null,
      state.treeVisible ? h(IdeResizer, { key: 'resize', store, state, tr }) : null,
      h('div', { key: 'editor', className: 'iw-editor' }, [
        h(IdeTabStrip, { key: 'tabs', store, state, tr, onBackToChat }),
        tab === undefined
          ? null
          : h(IdeCrumbs, {
            key: 'crumbs',
            // A jar tab has no workspace path: show where it really came from.
            path: tab.kind === 'jar' ? `${tab.dir}/${tab.name}` : tab.path,
          }),
        content,
      ]),
    ]),
    h(IdeStatusBar, { key: 'status', store, state, tab, tr }),
    state.paletteOpen
      ? h(IdePalette, {
        key: 'palette',
        store,
        tr,
        actions,
        onClose: () => store.setPaletteOpen(false),
      })
      : null,
  ])
}

// ---- 45-tracker.js -------------------------------------------------------
/**
 * Headless Session tracker.
 *
 * A global main panel is not a conversation, so the right-Sidebar controller
 * reports no Session "on screen" while this plugin's panel holds the column, and
 * the panel cannot learn which workspace to show from that controller at paint
 * time. This entry stays mounted in the frame's overlay layer (it renders
 * nothing) and remembers the Session that was on screen while the Conversation
 * still was.
 *
 * The workspace root comes from the Workspace list — `items[].path` for the
 * Workspace that accounts for the Session — and only falls back to the Session
 * row's own `cwd`. Both are read through the standard snapshot hooks, so the
 * resolution follows the same data the shipped navigation renders.
 */

/**
 * Resolve the Session and its absolute workspace root.
 *
 * Order of preference:
 *  1. the Session the right column reports as on screen;
 *  2. the Session the layout still retains for the main view;
 *  3. the Workspace that accounts for that Session (`items[].path`);
 *     then the Session row's `cwd`.
 *
 * @returns `{ sessionId, root }`; either may be missing, and the panel says so.
 */
function ideResolveTarget(mounted, sessionsState, workspacesState) {
  const byId = sessionsState?.byId ?? {}
  const ids = Array.isArray(sessionsState?.ids) ? sessionsState.ids : []
  let sessionId = typeof mounted === 'string' && mounted !== '' ? mounted : undefined
  if (sessionId === undefined) {
    sessionId = ids.find((id) => ((byId[id]?.retainedBy?.mainView) ?? 0) > 0)
  }
  if (sessionId === undefined) return { sessionId: undefined, root: '' }
  const items = Array.isArray(workspacesState?.items) ? workspacesState.items : []
  const workspace = items.find((item) => Array.isArray(item?.sessionIds) && item.sessionIds.includes(sessionId))
  const fromWorkspace = typeof workspace?.path === 'string' ? workspace.path : ''
  const fromSession = typeof byId[sessionId]?.cwd === 'string' ? byId[sessionId].cwd : ''
  return { sessionId, root: fromWorkspace !== '' ? fromWorkspace : fromSession }
}

/** The tracker entry. */
function IdeSessionTracker({ store, useSessions, useWorkspaces }) {
  const selectSessions = typeof useSessions === 'function' ? useSessions : () => undefined
  const selectWorkspaces = typeof useWorkspaces === 'function' ? useWorkspaces : () => undefined
  const sessions = selectSessions((snapshot) => snapshot)
  const workspaces = selectWorkspaces((snapshot) => snapshot)
  const target = ideResolveTarget(undefined, sessions, workspaces)

  // `mounted` turns undefined the moment a global panel takes the main column;
  // the remembered Session is what makes the panel survive that switch.
  useEffect(() => {
    if (typeof target.sessionId !== 'string') return
    store.rememberSession(target.sessionId)
  }, [target.sessionId, store])

  useEffect(() => {
    if (typeof target.root !== 'string' || target.root === '') return
    store.setRoot(target.root)
  }, [target.root, store])

  return null
}

// ---- 59-gesture-settings.js ----------------------------------------------
/**
 * The settings row that edits every code-workspace shortcut.
 *
 * The rows are **generated** from `IDE_SHORTCUTS`: add a shortcut to that table
 * and it appears here without touching this file. Keyboard commands are edited
 * in DSH's own 「编辑快捷键」 dialog (this row shows their current binding and
 * points there), pointer gestures are edited in place, and fixed sequences are
 * documented read-only — DSH's catalog cannot bind a click sequence.
 */

/**
 * The next gesture in the ring, skipping the one the other action already owns.
 *
 * @returns the gesture to apply, or the current one when nothing is free.
 */
function ideNextGesture(current, taken) {
  const start = IDE_GESTURE_CHOICES.indexOf(current)
  for (let step = 1; step <= IDE_GESTURE_CHOICES.length; step += 1) {
    const candidate = IDE_GESTURE_CHOICES[(start + step) % IDE_GESTURE_CHOICES.length]
    if (candidate !== taken) return candidate
  }
  return current
}

/** Locale label for one gesture choice. */
function ideGestureLabel(choice, platform, tr) {
  if (choice === 'meta' || choice === 'ctrl') return tr(idePlatformOf(platform).gestureLabelKey(choice))
  return tr(IDE_GESTURE_KEYS[choice])
}

/** The gesture actions, in settings order. */
const GESTURE_ACTIONS = ['definition', 'usages', 'chain']

/** One gesture row: a dropdown with the choices this platform can tell apart. */
function IdeGestureSelect(props) {
  const { entry, tr, platform, onPick } = props
  return h('select', {
    className: 'iw-gesture-select',
    value: entry.value,
    title: tr('gesturePickHint'),
    'aria-label': entry.label,
    onChange: (event) => onPick(entry.action, event.target.value),
  }, ideGestureChoices(platform).map((choice) => h('option', {
    key: choice,
    value: choice,
    disabled: entry.taken.includes(choice),
    title: entry.taken.includes(choice) ? tr('gestureTaken') : undefined,
  }, ideGestureLabel(choice, platform, tr))))
}

/** One generated row: label on the left, its control on the right. */
function IdeShortcutRow(props) {
  const { entry, tr, platform, onPick, onRecord, onReset, recording, busy } = props
  const editable = entry.kind === 'key' || entry.kind === 'sequence'
  return h('div', { className: 'iw-gesture-row' }, [
    h('span', { key: 'l', className: 'iw-gesture-label' }, entry.label),
    h('span', { key: 'right', className: 'iw-gesture-right' }, [
      entry.kind === 'gesture'
        ? h(IdeGestureSelect, { key: 'c', entry, tr, platform, onPick })
        : h('span', {
          key: 'k',
          className: `iw-gesture-keys${recording ? ' recording' : ''}`,
        }, recording ? tr('ksRecording') : entry.text),
      editable
        ? h('button', {
          key: 'b',
          type: 'button',
          className: 'iw-gesture-chip',
          disabled: busy === true,
          onClick: () => onRecord(entry.id),
        }, recording ? tr('ksCancel') : tr('ksChange'))
        : null,
      editable
        ? h('button', {
          key: 'r',
          type: 'button',
          className: 'iw-gesture-chip',
          disabled: busy === true || entry.modified !== true,
          onClick: () => onReset(entry.id),
        }, tr('ksReset'))
        : null,
    ]),
  ])
}

/**
 * The General-settings row, expanding into the shortcut list in place.
 *
 * Inline rather than a dialog: `shell.overlay` renders below the settings dialog,
 * so a dialog opened from here would be covered by it.
 */
/**
 * The line under the repository field.
 *
 * A placeholder alone is too faint to confirm a detection, so the row states the
 * path that is really in use, where it came from, and whether it exists.
 */
function mavenRowHint(tr, state) {
  const detected = typeof state.mavenRepoDetected === 'string' ? state.mavenRepoDetected : ''
  const manual = typeof state.mavenRepo === 'string' ? state.mavenRepo : ''
  const inUse = manual !== '' ? manual : detected
  if (inUse === '') {
    return h('div', { key: 'mavenhint', className: 'iw-settings-hint' }, tr('settingsMavenRepoDetecting'))
  }
  const source = manual !== '' ? tr('settingsMavenRepoManual') : tr('settingsMavenRepoAuto')
  const missing = manual === '' && detected !== '' && state.mavenRepoDetectedExists !== true
  return h('div', { key: 'mavenhint', className: `iw-settings-hint${missing ? ' warn' : ''}` }, [
    h('span', { key: 's' }, `${tr('settingsMavenRepoInUse')}（${source}）：`),
    h('span', { key: 'p', className: 'iw-settings-hint-path' }, inUse),
    missing ? h('span', { key: 'm', className: 'iw-settings-hint-warn' }, ` · ${tr('settingsMavenRepoMissingDir')}`) : null,
  ])
}

function IdeWorkspaceSettingsItem(props) {
  const { translate, store, platform, runtime, onPick, onRecord, onReset } = props
  const tr = typeof translate === 'function' ? translate : (key) => key
  const state = useSyncExternalStore(store.subscribe, store.getState, store.getState)
  const open = state.gestureEditorOpen === true
  const [shortcutsOpen, setShortcutsOpen] = React.useState(false)
  const [fontsOpen, setFontsOpen] = React.useState(false)
  // The detected repository is only known after the Host answers; ask once if
  // the panel was never mounted, so the row can show what is really in use.
  React.useEffect(() => {
    if (state.mavenRepoDetected !== '') return undefined
    let cancelled = false
    void ideDoctorQuery().then((found) => {
      if (!cancelled && found.ok === true && found.mavenRepo !== '') {
        store.setMavenRepoDetected(found.mavenRepo, found.mavenRepoExists === true)
      }
    })
    return () => { cancelled = true }
  }, [state.mavenRepoDetected, store])
  const gestures = state.gestures ?? { definition: 'double', usages: 'meta', chain: 'alt' }
  const bindings = state.shortcutBindings ?? {}

  // Generated: one row per registry entry, no per-shortcut code here.
  const rows = IDE_SHORTCUTS.map((command) => {
    if (command.kind === 'gesture') {
      return {
        id: command.id,
        kind: 'gesture',
        action: command.action,
        label: tr(command.labelKey),
        value: gestures[command.action],
        // Every other action's gesture is unavailable here: one gesture, one job.
        taken: GESTURE_ACTIONS.filter((key) => key !== command.action).map((key) => gestures[key]),
      }
    }
    if (command.kind === 'sequence') {
      const sequence = bindings[command.id] ?? ideSequenceDefault(command, runtime)
      return {
        id: command.id,
        kind: 'sequence',
        label: tr(command.labelKey),
        text: ideSequenceLabel(sequence, tr),
        modified: bindings[command.id] != null,
      }
    }
    const binding = bindings[command.id] ?? ideShortcutDefault(command, runtime)
    const keys = ideBindingKeys(binding, platform)
    return {
      id: command.id,
      kind: 'key',
      label: tr(command.labelKey),
      text: keys.length === 0 ? tr('ksUnbound') : keys.join(' '),
      modified: bindings[command.id] != null,
    }
  })

  const codeSize = Number.isFinite(state.codeFontSize) ? state.codeFontSize : 12.5
  const treeSize = Number.isFinite(state.treeFontSize) ? state.treeFontSize : 14.5
  const stepper = (key, label, value, set) => h('div', { key, className: 'iw-gesture-row' }, [
    h('span', { key: 'l', className: 'iw-gesture-label' }, label),
    h('span', { key: 's', className: 'iw-gesture-right' }, [
      h('button', {
        key: 'minus',
        type: 'button',
        className: 'iw-gesture-chip',
        onClick: () => set(value - 0.5),
      }, '−'),
      h('span', { key: 'v', className: 'iw-gesture-keys' }, `${value} px`),
      h('button', {
        key: 'plus',
        type: 'button',
        className: 'iw-gesture-chip',
        onClick: () => set(value + 0.5),
      }, '+'),
      h('button', {
        key: 'reset',
        type: 'button',
        className: 'iw-gesture-chip',
        disabled: key === 'code' ? codeSize === 12.5 : treeSize === 14.5,
        onClick: () => set(key === 'code' ? 12.5 : 14.5),
      }, tr('ksReset')),
    ]),
  ])

  return h(React.Fragment, null, [
    h(IdeStyles, { key: 'style' }),
    h('div', { key: 'row', className: 'iw-gesture-item' }, [
      h('div', { key: 'text', className: 'iw-gesture-item-text' }, [
        h('span', { key: 't', className: 'iw-gesture-item-title' }, tr('settingsTitle')),
        h('span', { key: 'h', className: 'iw-gesture-item-hint' }, tr('settingsHint')),
      ]),
      h('button', {
        key: 'b',
        type: 'button',
        className: 'iw-gesture-btn',
        'aria-expanded': open ? 'true' : 'false',
        onClick: () => store.setGestureEditor(!open),
      }, open ? tr('gestureClose') : tr('gestureEdit')),
    ]),
    open
      ? h('div', { key: 'panel', className: 'iw-gesture-panel' }, [
        // Shortcuts: a sub-item, so the section keeps room for more settings.
        h('div', { key: 'sc', className: 'iw-settings-item' }, [
          h('span', { key: 'l', className: 'iw-settings-item-label' }, tr('gestureSection')),
          h('button', {
            key: 'b',
            type: 'button',
            className: 'iw-gesture-chip',
            onClick: () => setShortcutsOpen(!shortcutsOpen),
          }, shortcutsOpen ? tr('gestureClose') : `${tr('gestureEdit')} (${rows.length})`),
        ]),
        shortcutsOpen
          ? h('div', { key: 'sclist', className: 'iw-settings-body' }, [
            h('div', { key: 'hint', className: 'iw-gesture-hint' }, tr('gestureHint')),
            state.gestureIssue === '' ? null : h('div', { key: 'issue', className: 'iw-gesture-issue' }, state.gestureIssue),
            h('div', { key: 'rows', className: 'iw-gesture-rows' }, rows.map((entry) => h(IdeShortcutRow, {
              key: entry.id,
              entry,
              tr,
              platform,
              onPick,
              onRecord,
              onReset,
              recording: state.gestureRecording === entry.id,
              busy: state.gestureBusy === true,
            }))),
          ])
          : null,
        h('div', { key: 'basic', className: 'iw-settings-group' }, tr('settingsBasic')),
        h('div', { key: 'font', className: 'iw-settings-item' }, [
          h('span', { key: 'l', className: 'iw-settings-item-label' }, tr('settingsFont')),
          h('button', {
            key: 'b',
            type: 'button',
            className: 'iw-gesture-chip',
            onClick: () => setFontsOpen(!fontsOpen),
          }, fontsOpen ? tr('gestureClose') : `${codeSize} / ${treeSize} px`),
        ]),
        fontsOpen
          ? h('div', { key: 'fontbody', className: 'iw-settings-body' }, [
            stepper('code', tr('settingsCodeFont'), codeSize, (next) => store.setCodeFontSize(next)),
            stepper('tree', tr('settingsTreeFont'), treeSize, (next) => store.setTreeFontSize(next)),
          ])
          : null,
        // Dependency sources come from a Maven repository; the Host detects the
        // usual places, and this field covers repositories kept anywhere else.
        h('div', { key: 'maven', className: 'iw-settings-maven' }, [
          h('div', { key: 'row', className: 'iw-settings-maven-row' }, [
            h('span', { key: 'l', className: 'iw-settings-item-label' }, tr('settingsMavenRepo')),
            h('input', {
              key: 'i',
              className: 'iw-settings-input',
              type: 'text',
              spellCheck: false,
              defaultValue: state.mavenRepo,
              placeholder: tr('settingsMavenRepoAuto'),
              title: tr('settingsMavenRepoHint'),
              onKeyDown: (event) => {
                if (event.key === 'Enter') event.currentTarget.blur()
              },
              onBlur: (event) => store.setMavenRepo(event.target.value),
            }),
          ]),
          mavenRowHint(tr, state),
        ]),
      ])
      : null,
  ])
}

/**
 * The tab context menu, mirroring IDEA's.
 *
 * Items that need data this plugin does not own — DSH keeps no draft API for
 * 「添加到智能体上下文」 — copy an `@`-reference instead and say so, rather than
 * pretending to do something.
 */
function IdeTabMenu({ store, state, tr, copy }) {
  const menu = state.tabMenu
  if (menu === null || menu === undefined) return null
  const path = menu.path
  const tab = state.tabs.find((entry) => entry.path === path)
  if (tab === undefined) return null
  const run = (action) => () => {
    store.setTabMenu(null)
    action()
  }
  // Icons on the left and the label next to them, the way an editor's menu reads.
  const items = [
    { key: 'close', icon: IdeCloseIcon, label: tr('tabMenuClose'), run: () => store.closeTab(path) },
    { key: 'others', icon: IdeLayersIcon, label: tr('tabMenuCloseOthers'), run: () => store.closeOthers(path) },
    { key: 'all', icon: IdeStackIcon, label: tr('tabMenuCloseAll'), run: () => store.closeAllTabs() },
    { key: 'unmodified', icon: IdeDotIcon, label: tr('tabMenuCloseUnmodified'), run: () => store.closeUnmodified() },
    { key: 'left', icon: IdeArrowLeftIcon, label: tr('tabMenuCloseLeft'), run: () => store.closeToLeft(path) },
    { key: 'right', icon: IdeArrowRightIcon, label: tr('tabMenuCloseRight'), run: () => store.closeToRight(path) },
    { key: 'readonly', icon: IdeLockIcon, label: tr('tabMenuCloseReadOnly'), run: () => store.closeReadOnly() },
    { key: 'sep1', separator: true },
    { key: 'context', icon: IdeAtIcon, label: tr('tabMenuAddToContext'), run: () => copy(`@${path}`) },
    { key: 'copy', icon: IdeCopyIcon, label: tr('tabMenuCopyPath'), run: () => copy(path) },
  ]
  return h(React.Fragment, null, [
    h(IdeStyles, { key: 'style' }),
    h('div', {
      key: 'backdrop',
      className: 'iw-menu-backdrop',
      onPointerDown: () => store.setTabMenu(null),
      onContextMenu: (event) => {
        event.preventDefault()
        store.setTabMenu(null)
      },
    }, h('div', {
      key: 'menu',
      className: 'iw-menu',
      role: 'menu',
      'aria-label': tr('tabMenuLabel'),
      // Keep the menu inside the window when the tab sits near an edge.
      style: {
        left: `${Math.min(menu.x, Math.max(8, (globalThis.innerWidth || 1280) - 260))}px`,
        top: `${Math.min(menu.y, Math.max(8, (globalThis.innerHeight || 800) - 340))}px`,
      },
      onPointerDown: (event) => event.stopPropagation(),
    }, items.map((item) => (item.separator === true
      ? h('div', { key: item.key, className: 'iw-menu-sep' })
      : h('button', {
        key: item.key,
        type: 'button',
        role: 'menuitem',
        className: 'iw-menu-item',
        onClick: run(item.run),
      }, [
        h('span', { key: 'ic', className: 'iw-menu-icon' }, h(item.icon, { size: 13 })),
        h('span', { key: 'lb', className: 'iw-menu-label' }, item.label),
      ]))))),
  ])
}

/** The code gutter's context menu: Git annotate for this file. */
function IdeGutterMenu({ store, state, tr }) {
  const menu = state.codeMenu
  if (menu === null || menu === undefined) return null
  const path = menu.path
  const on = state.annotate?.[path] === true
  const run = (action) => () => {
    store.setCodeMenu(null)
    action()
  }
  const items = [
    {
      key: 'annotate',
      icon: IdeClockIcon,
      label: on ? tr('gutterMenuUnannotate') : tr('gutterMenuAnnotate'),
      run: () => store.toggleAnnotate(path),
    },
  ]
  return h(React.Fragment, null, [
    h(IdeStyles, { key: 'style' }),
    h('div', {
      key: 'backdrop',
      className: 'iw-menu-backdrop',
      onPointerDown: () => store.setCodeMenu(null),
      onContextMenu: (event) => {
        event.preventDefault()
        store.setCodeMenu(null)
      },
    }, h('div', {
      key: 'menu',
      className: 'iw-menu',
      role: 'menu',
      'aria-label': tr('gutterMenuLabel'),
      style: {
        left: `${Math.min(menu.x, Math.max(8, (globalThis.innerWidth || 1280) - 260))}px`,
        top: `${Math.min(menu.y, Math.max(8, (globalThis.innerHeight || 800) - 80))}px`,
      },
      onPointerDown: (event) => event.stopPropagation(),
    }, items.map((item) => h('button', {
      key: item.key,
      type: 'button',
      role: 'menuitem',
      className: 'iw-menu-item',
      onClick: run(item.run),
    }, [
      h('span', { key: 'ic', className: 'iw-menu-icon' }, h(item.icon, { size: 13 })),
      h('span', { key: 'lb', className: 'iw-menu-label' }, item.label),
    ])))),
  ])
}

// ---- 60-jump.js ----------------------------------------------------------
/**
 * Reference interception: a file address opened anywhere in the shell becomes a
 * jump in the code workspace.
 *
 * DSH resolves `dsh-resource://file/…` addresses with a ranked type registry
 * (VS Code's editor-resolver model): a whitelist glob narrows the candidates, a
 * veto predicate removes the rest, and survivors rank by priority band. A type
 * shipped outside the product declares the `extension` band, which outranks every
 * viewer shipped here — so claiming the address and forwarding it is a supported
 * mechanism, not a hack.
 *
 * Two deliberate limits keep the blast radius small:
 *
 *  - the type claims nothing until the workspace panel has been opened once in
 *    this page, so a user who never uses it keeps the shipped preview everywhere;
 *  - `canOpen` vetoes anything that is not text, so images, PDFs and Office
 *    files keep their own viewers.
 */

/** Identity of the claiming type, and the `sidebar.right.pane.tab` key of its body. */
const IDE_FILE_TYPE_ID = 'dsh-ide-window:file'

/** The band this type declares; `extension` is the highest. */
const IDE_FILE_KIND = 'dsh-ide-window-file'

/** Extensions that are never text, even though a viewer may exist for them. */
const IDE_BINARY_EXT = new Set([
  'png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'ico', 'svg', 'pdf', 'zip', 'gz', 'tar', 'tgz',
  'jar', 'war', 'class', 'so', 'dylib', 'dll', 'exe', 'bin', 'mp3', 'mp4', 'mov', 'wav', 'woff',
  'woff2', 'ttf', 'otf', 'docx', 'xlsx', 'pptx', 'doc', 'xls', 'ppt', 'db', 'sqlite', 'lock',
])

/**
 * Extensions this panel must NOT claim.
 *
 * The shipped viewers render markdown, html, csv and plain text better than a
 * source view can — rendered prose, tables, syntax-highlighted previews — so
 * those stay where they are, as do every binary and Office format. Claiming
 * them would make the app worse, which is the one thing an interceptor must
 * never do.
 */
const IDE_VETO_EXT = new Set([
  'md', 'markdown', 'mdx', 'html', 'htm', 'csv', 'tsv', 'txt', 'log', 'rst', 'adoc',
])

/** Extension-less names worth claiming as text. */
const IDE_TEXT_NAMES = new Set([
  'makefile', 'dockerfile', 'rakefile', 'gemfile', 'procfile', 'license', 'licence', 'notice',
  'readme', 'changelog', 'authors', 'contributors', 'codeowners', 'jenkinsfile', 'vagrantfile',
])

/** Decode one address segment, tolerating an encoding the sender did not apply. */
function ideDecodeSegment(segment) {
  try {
    return decodeURIComponent(segment)
  } catch (error) {
    void error
    return segment
  }
}

/**
 * Read a `dsh-resource://file/…` address into its parts.
 *
 * Grammar (see the shipped `file-address` module): `…/file/session/<sessionId>/<path>`
 * names a file through one Session — the path is workspace-relative or absolute
 * — and `…/file/absolute/<path>` names it by absolute path with the leading `/`
 * dropped.
 *
 * @returns `{ scope, sessionId, path }`, or `undefined` for anything else.
 */
/**
 * A path the shell hands out, as a path inside this workspace.
 *
 * The built-in 「已编辑」 card stores the absolute path of each file next to the
 * row; the panel addresses files relative to its root. A path outside the root
 * keeps the card's own display text, which is already workspace-relative.
 */
function ideRelativeWorkspacePath(absolute, root, fallback) {
  if (typeof absolute === 'string' && absolute !== '' && typeof root === 'string' && root !== '') {
    if (absolute === root) return ''
    if (absolute.startsWith(`${root}/`)) return absolute.slice(root.length + 1)
  }
  return typeof fallback === 'string' ? fallback : ''
}

function ideParseFileAddress(address) {
  const prefix = 'dsh-resource://file/'
  if (typeof address !== 'string' || !address.startsWith(prefix)) return undefined
  const end = address.search(/[?#]/)
  const body = address.slice(prefix.length, end === -1 ? undefined : end)
  const segments = body.split('/').map(ideDecodeSegment)
  const scope = segments[0]
  if (scope === 'absolute') {
    const path = segments.slice(1).join('/')
    return path === '' ? undefined : { scope: 'absolute', sessionId: '', path: `/${path}` }
  }
  if (scope === 'session') {
    const sessionId = segments[1]
    if (sessionId === undefined || sessionId === '') return undefined
    return { scope: 'session', sessionId, path: segments.slice(2).join('/') }
  }
  return undefined
}

/** Whether the address names a file this panel can display as source. */
function ideIsTextAddress(address) {
  const parsed = ideParseFileAddress(address)
  if (parsed === undefined || parsed.path === '') return false
  const name = ideBasename(parsed.path)
  if (name === '') return false
  const dot = name.lastIndexOf('.')
  const ext = dot < 0 ? '' : name.slice(dot + 1).toLowerCase()
  if (IDE_BINARY_EXT.has(ext) || IDE_VETO_EXT.has(ext)) return false
  if (ext !== '') return ideLangOf(name) !== ''
  return IDE_TEXT_NAMES.has(name.toLowerCase())
}

/**
 * The claiming tab body.
 *
 * It draws nothing: the tab exists only for the address it was opened with, so
 * the effect forwards that address to the workspace and the tab is closed again.
 */
function IdeFileJump(props) {
  const readInfo = typeof props?.useTabInfo === 'function'
    ? props.useTabInfo
    : (typeof props?.tabInfo === 'function' ? props.tabInfo : () => undefined)
  const info = readInfo()
  const navigation = info?.tab?.navigation
  const address = typeof navigation?.address === 'string' ? navigation.address : undefined
  const revision = typeof navigation?.revision === 'number' ? navigation.revision : 0
  const tabId = info?.tab?.id
  const jump = props?.jump

  useEffect(() => {
    if (address === undefined || typeof jump !== 'function') return
    jump(tabId, address, navigation?.params)
  }, [address, revision, tabId, jump, navigation])

  return null
}

// ---- 65-lsp.js -----------------------------------------------------------
/**
 * Semantic navigation, backed by the Host's LSP seam.
 *
 * DSH exposes exactly four semantic queries on `ctx.lsp` and no protocol escape
 * hatch, so the browser half asks the plugin's own Host route (see `index.js`)
 * for `goToDefinition`, `goToImplementation` and `findReferences`, and gets back
 * workspace-relative paths with 1-based lines.
 *
 * Reference rows carry their source line, which LSP does not send: it is read
 * here, once per distinct file, so the popup can show code instead of a bare
 * coordinate.
 */

/** Resolve the plugin's route against the page base, keeping proxy prefixes. */
function ideLspUrl() {
  const base = typeof document !== 'undefined' && typeof document.baseURI === 'string'
    ? document.baseURI
    : 'http://dsh.internal/'
  return new URL('dsh-ide/lsp', base).href
}

/**
 * Run one query through the Host.
 *
 * @param payload - `{ operation, filePath, workspaceRoot, position }`.
 * @returns the normalized `{ kind, locations | hover }`.
 * @throws an Error whose `code` is the Host's stable failure code.
 */
/**
 * Operations the server answered "not supported" for.
 *
 * A JSON-RPC `-32601` (or a message saying so) will not change within a
 * session; asking again only produces another error banner and another wait
 * before the text fallback.
 */
const ideLspUnsupported = new Set()

/**
 * Whether one error says the machine has no licence for the language server.
 *
 * The JetBrains server refuses every request with `-32802: no active JetBrains
 * license`; the only cure is signing in with a licensed account outside the
 * plugin, so this is not retried on every click.
 */
function ideLspNeedsLicense(error) {
  const text = `${error?.detail ?? ''} ${error?.message ?? ''}`
  return /-32802|no active JetBrains license/i.test(text)
}

/** Set once the server answered that this machine has no licence. */
let ideLspLicenseMissing = false

/** The URL the next real click should open, and whether we asked the host already. */
let ideLicenseUrlPending = ''
let ideLicenseRequested = false

/**
 * Start the JetBrains sign-in through the host.
 *
 * The host runs `intellij-server license login --browser` and returns the URL
 * the account flow opened. A popup without a user gesture is easy to block, so
 * the URL is also parked for the next click (`ideFlushLicenseUrl`). When the
 * machine is already signed in without a licence the tool prints guidance
 * instead of a URL; the account's licence page is the useful destination then.
 */
async function ideRequestLicenseLogin() {
  if (ideLicenseRequested) return
  ideLicenseRequested = true
  const base = typeof document !== 'undefined' && typeof document.baseURI === 'string'
    ? document.baseURI
    : 'http://dsh.internal/'
  let answer
  try {
    const response = await fetch(new URL('dsh-ide/license', base).href, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ action: 'open' }),
    })
    answer = await response.json()
  } catch (error) {
    void error
    answer = undefined
  }
  // The host opens the page with the platform browser (`open`/`xdg-open`),
  // which is the only reliable way out of a webview. `window.open` stays as a
  // fallback when the host could not launch anything.
  if (answer?.value?.opened === true) return
  const url = typeof answer?.value?.url === 'string' && answer.value.url !== ''
    ? answer.value.url
    : 'https://account.jetbrains.com/licenses'
  ideLicenseUrlPending = url
  try {
    const opened = globalThis.open?.(url, '_blank', 'noopener')
    if (opened !== null && opened !== undefined) ideLicenseUrlPending = ''
  } catch (error) {
    void error
  }
}

/** Open the parked licence page while a click's user gesture is still fresh. */
function ideFlushLicenseUrl() {
  if (ideLicenseUrlPending === '') return
  const url = ideLicenseUrlPending
  ideLicenseUrlPending = ''
  try {
    globalThis.open?.(url, '_blank', 'noopener')
  } catch (error) {
    void error
  }
}

/** Whether one error means the server does not implement this operation. */
function ideLspUnsupportedBy(error) {
  const text = `${error?.detail ?? ''} ${error?.message ?? ''}`
  return /-32601|method not found|not supported|unsupported/i.test(text)
}

async function ideLspQuery(payload, signal) {
  if (ideLspLicenseMissing) {
    const refused = new Error('no active JetBrains license')
    refused.code = 'LSP_NO_LICENSE'
    refused.detail = 'the language server has no active licence on this machine'
    throw refused
  }
  if (ideLspUnsupported.has(payload?.operation)) {
    const skipped = new Error('operation not supported by the server')
    skipped.code = 'lsp-unsupported'
    throw skipped
  }
  let response
  try {
    response = await fetch(ideLspUrl(), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(payload),
      signal,
    })
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') throw error
    const failure = new Error('network')
    failure.code = 'network'
    throw failure
  }
  const parsed = await response.json().catch(() => null)
  if (parsed === null) {
    const failure = new Error(`HTTP ${response.status}`)
    failure.code = `http-${response.status}`
    throw failure
  }
  if (parsed.ok !== true) {
    const failure = new Error(parsed.error?.code ?? `http-${response.status}`)
    failure.code = parsed.error?.code ?? `http-${response.status}`
    failure.detail = parsed.error?.message ?? ''
    if (ideLspUnsupportedBy(failure) && typeof payload?.operation === 'string') {
      ideLspUnsupported.add(payload.operation)
    }
    if (ideLspNeedsLicense(failure)) {
      // First refusal: start the sign-in so the page is one click away.
      if (!ideLspLicenseMissing) void ideRequestLicenseLogin()
      ideLspLicenseMissing = true
    }
    throw failure
  }
  return parsed.value
}

/** One query addressed to the panel's current workspace. */
function ideLspPayload(store, operation, tabPath, position) {
  const state = store.getState()
  return {
    operation,
    filePath: ideAbs(state.rootPath, tabPath),
    workspaceRoot: state.rootPath,
    position,
  }
}

/**
 * Definition first, implementation as the fallback.
 *
 * Ctrl/Cmd+click on an interface method resolves to the interface declaration;
 * asking for the implementation when that yields nothing is what makes the same
 * gesture land in the class the user actually wanted.
 *
 * @returns locations `{ path, line, character }`, best first.
 */
async function ideLspDefinition(store, tabPath, position, symbolName, timeline) {
  const request = async (operation) => {
    const started = ideNow()
    const result = await ideLspQuery(ideLspPayload(store, operation, tabPath, position))
    timeline?.mark(operation === 'goToDefinition' ? 'lsp' : operation, ideNow() - started)
    return result.locations ?? []
  }

  let located = await request('goToDefinition')
  if (located.length === 0) located = await request('goToImplementation')

  const fieldName = ideBeanFieldName(symbolName)
  // Everything below is bean-accessor work: any other symbol is answered by the
  // one query above, with no file read at all.
  if (fieldName === undefined) return located

  if (located.length === 0) {
    // A Lombok accessor the server cannot resolve has no declaration to follow;
    // the field is still in the open file, so that is the last resort.
    const started = ideNow()
    const lines = await ideFileLines(store, tabPath)
    timeline?.mark('read', ideNow() - started)
    const line = lines === null ? 0 : ideFindFieldLine(lines, fieldName)
    if (line > 0) return [{ path: tabPath, line, character: 0 }]
    // The property may live in another class: `Type::getValue` names it.
    const owned = await ideAccessorOwnerField(store, tabPath, position, fieldName)
    return owned === undefined ? located : [owned]
  }

  if (located.length > 1) return located

  // The server usually resolves a Lombok accessor straight to its field, and
  // reading the destination is cheaper than a second query. Only an accessor
  // that resolved to its own body still needs the field resolved on its behalf.
  const started = ideNow()
  const lines = await ideFileLines(store, located[0].path)
  timeline?.mark('read', ideNow() - started)
  if (lines === null) return located
  // The destination declares the *accessor* (its own name followed by a
  // parameter list) when it did not resolve to the field; a field line carries
  // the property name instead, so the accessor name is what decides this.
  if (!ideLineHasMethodAt(lines[located[0].line - 1], symbolName)) return located
  const field = await ideAccessorField(store, located[0], fieldName, lines, timeline)
  return field === undefined ? located : [field, ...located.slice(1)]
}

/**
 * The class named before `::` on the clicked line, as in `Type::getValue`.
 *
 * A method reference is the one accessor call that states its owner in the
 * source, so a Lombok getter the engine cannot resolve still has somewhere to go.
 */
function ideMethodRefOwner(lineText, column) {
  const before = String(lineText ?? '').slice(0, Math.max(0, column))
  const match = /([A-Z][\w$]*)\s*::\s*[\w$]*$/.exec(before)
  return match === null ? '' : match[1]
}

/**
 * Resolve a Lombok accessor through its owner's source file.
 *
 * Used when the engine returns no declaration and the field is not in the open
 * file: `ExchangeRateInnerResp::getBusinessDate` names the class, so the field is
 * looked up in that class's own file.
 */
async function ideAccessorOwnerField(store, tabPath, position, fieldName) {
  const lines = await ideFileLines(store, tabPath)
  if (lines === null) return undefined
  const owner = ideMethodRefOwner(lines[position.line] ?? '', position.character)
  if (owner === '') return undefined
  const found = await store.searchFiles(`${owner}.java`)
  if (found.ok !== true) return undefined
  const target = found.matches.find((match) => match.path.split('/').pop() === `${owner}.java`)
  if (target === undefined) return undefined
  const ownerLines = await ideFileLines(store, target.path)
  if (ownerLines === null) return undefined
  const line = ideFindFieldLine(ownerLines, fieldName)
  return line > 0 ? { path: target.path, line, character: 0 } : undefined
}

/**
 * The 1-based line of a field declaration for `name`, or `0`.
 *
 * Deliberately strict: the name must be followed by `;` or `=`, so a method
 * returning the same type (`name(`) or a call (`name(arg)`) never matches.
 */
function ideFindFieldLine(lines, name) {
  const pattern = new RegExp(
    '^\\s*(?:(?:private|protected|public|final|static|transient|volatile)\\s+)*'
    + `[\\w$<>\\[\\],.?]+(?:\\s+[\\w$<>\\[\\],.?]+)*\\s+${name}\\s*(?:[;=])`,
  )
  for (let index = 0; index < lines.length; index += 1) {
    if (pattern.test(lines[index])) return index + 1
  }
  return 0
}

/** Whether `word` is followed by a parameter list on that line (a method, not a field). */
function ideLineHasMethodAt(line, word) {
  if (typeof line !== 'string') return false
  const column = ideFindWordColumn(line, word)
  if (column < 0) return false
  let index = column + word.length
  while (index < line.length && (line[index] === ' ' || line[index] === '\t')) index += 1
  return line[index] === '('
}

/**
 * Resolve a bean accessor to the property it reads or writes.
 *
 * The definition of `setSuspendedCount` is the setter's own body, which is not
 * where a Java developer wants to land when following a property. The field name
 * follows from the method name, so this finds that identifier inside the
 * accessor and asks the language server for *its* definition — the field
 * declaration, resolved semantically rather than guessed from the text.
 *
 * @returns the field's location, or `undefined` when the accessor is abstract,
 *   generated, or already resolves to the field itself.
 */
async function ideAccessorField(store, location, fieldName, lines, timeline) {
  if (fieldName === undefined || typeof location?.path !== 'string') return undefined
  if (lines === null || lines === undefined) return undefined
  const from = Math.max(0, location.line - 1)
  const to = Math.min(lines.length, from + 14)
  // `this.<field>` is the unambiguous spelling a setter uses; a bare occurrence
  // could be the parameter of the same name, so it is only the fallback. Either
  // way a column inside the parameter list is skipped.
  const candidates = []
  for (let index = from; index < to; index += 1) {
    const line = lines[index]
    const column = ideFindWordColumn(line, fieldName)
    if (column < 0 || ideInsideParens(line, column)) continue
    const before = line.slice(Math.max(0, column - 5), column)
    candidates.push({ index, column, qualified: /this\.$/.test(before) })
  }
  candidates.sort((left, right) => Number(right.qualified) - Number(left.qualified))
  for (const candidate of candidates) {
    const { index, column } = candidate
    try {
      const started = ideNow()
      const result = await ideLspQuery({
        operation: 'goToDefinition',
        filePath: ideAbs(store.getState().rootPath, location.path),
        workspaceRoot: store.getState().rootPath,
        position: { line: index, character: column },
      })
      timeline?.mark('field', ideNow() - started)
      const field = (result.locations ?? [])[0]
      if (field !== undefined && field.path === location.path && field.line !== location.line) return field
    } catch (error) {
      void error
      return undefined
    }
  }
  return undefined
}

/** A monotonic timestamp, falling back to the clock when `performance` is absent. */
function ideNow() {
  const performance = globalThis.performance
  return performance !== undefined && typeof performance.now === 'function' ? performance.now() : Date.now()
}

/**
 * One interaction's timings.
 *
 * Navigation latency is dominated by round trips, so the useful thing to ship is
 * a measurement: every interaction reports where its milliseconds went, in the
 * banner and the console. Nothing is kept between interactions.
 */
function ideTimeline() {
  const started = ideNow()
  const marks = []
  return {
    mark(label, milliseconds) {
      marks.push([label, Math.round(milliseconds)])
      return milliseconds
    },
    total() {
      return Math.round(ideNow() - started)
    },
    phases() {
      return marks.map(([name, ms]) => `${name} ${ms}ms`).join(' \u00b7 ')
    },
    report(label) {
      const parts = marks.map(([name, ms]) => `${name} ${ms}ms`).join(' \u00b7 ')
      try {
        globalThis.console?.debug?.(`[dsh-ide-window] ${label}: ${parts} \u00b7 total ${Math.round(ideNow() - started)}ms`)
      } catch (error) {
        void error
      }
    },
  }
}

/** How many accessor call sites may be checked before giving up on an anchor. */
const IDE_MAX_ANCHOR_TRIES = 8

/** The property a Java bean accessor works on: `getX`/`setX`/`isX` \u2192 `x`. */
/**
 * The line declaring an annotation attribute, ignoring mentions in comments.
 *
 * Annotation sources often document themselves with `{@link #name()}`, so a naive
 * search lands in the javadoc instead of the declaration.
 *
 * @returns the 0-based index, or -1 when no declaration is found.
 */
function ideAttributeLineIn(lines, attribute) {
  if (!Array.isArray(lines) || typeof attribute !== 'string' || attribute === '') return -1
  const call = new RegExp(`\\b${attribute}\\s*\\(`)
  const declaration = new RegExp(`^\\s*(?:(?:public|protected|private|abstract|default|static|final)\\s+)*[\\w<>\\[\\].?, ]+\\b${attribute}\\s*\\(`)
  let fallback = -1
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index]
    if (!call.test(line)) continue
    const trimmed = line.trim()
    if (trimmed.startsWith('*') || trimmed.startsWith('//') || trimmed.startsWith('/*') || trimmed.startsWith('@')) continue
    if (declaration.test(line)) return index
    if (fallback < 0) fallback = index
  }
  return fallback
}

/**
 * The annotation type whose argument list contains `position`, if any.
 *
 * Annotation attributes are written `@Log(name = "x")`, so a click on `name`
 * resolves nothing on its own: the declaration lives in the annotation type, and
 * that type is usually imported from a dependency.
 *
 * @returns the simple type name, or an empty string when the position is not
 * inside an annotation's arguments.
 */
function ideAnnotationTypeAt(lines, position) {
  const line = lines?.[position?.line] ?? ''
  if (line === '') return ''
  // A multi-line annotation puts the type on an earlier line, so look back a
  // little; the stray `)` check below keeps an already-closed annotation out.
  const start = Math.max(0, position.line - 3)
  const text = lines.slice(start, position.line).join('\n') + '\n' + line.slice(0, position.character)
  const matches = [...text.matchAll(/@([A-Z][\w$]*)\s*\(/g)]
  if (matches.length === 0) return ''
  const last = matches[matches.length - 1]
  let depth = 0
  for (const character of text.slice(last.index + last[0].length)) {
    if (character === '(') depth += 1
    else if (character === ')') {
      depth -= 1
      if (depth < 0) return ''
    }
  }
  return last[1]
}

function ideBeanFieldName(name) {
  const match = /^(?:get|set|is)([A-Z][\w$]*)$/.exec(typeof name === 'string' ? name : '')
  if (match === null) return undefined
  return match[1].charAt(0).toLowerCase() + match[1].slice(1)
}

/** Column of one whole-word occurrence, or `-1`. */
function ideFindWordColumn(line, word) {
  const pattern = new RegExp(`(^|[^\\w$])(${word})(?![\\w$])`)
  const match = pattern.exec(line)
  if (match === null) return -1
  return match.index + match[1].length
}

/** Whether a column sits inside a parameter list on that line. */
function ideInsideParens(line, column) {
  let depth = 0
  for (let index = 0; index < column && index < line.length; index += 1) {
    if (line[index] === '(') depth += 1
    else if (line[index] === ')') depth = Math.max(0, depth - 1)
  }
  return depth > 0
}

/** Every line of one workspace file, or `null` when it cannot be read. */
async function ideFileLines(store, path) {
  const state = store.getState()
  if (typeof state.sessionId !== 'string' || state.rootPath === '') return null
  const result = await store.readText(state.sessionId, state.rootPath, path)
  if (!result.ok) return null
  return String(result.value).split('\n')
}

/** Read one line of one file, memoised per call so a popup costs one read per file. */
async function ideLineText(store, path, line, cache) {
  if (cache.has(path)) {
    const lines = cache.get(path)
    if (lines === null) return ''
    return lines[line - 1] ?? ''
  }
  const state = store.getState()
  if (typeof state.sessionId !== 'string') return ''
  const result = await store.readText(state.sessionId, state.rootPath, path)
  if (!result.ok) {
    cache.set(path, null)
    return ''
  }
  const lines = String(result.value).split('\n')
  cache.set(path, lines)
  return lines[line - 1] ?? ''
}

/**
 * Attach each location's source line.
 *
 * LSP answers with a range, not with code, so every row a popup shows is
 * completed here \u2014 one read per distinct file, never one per row.
 */
async function ideWithSnippets(store, locations) {
  const cache = new Map()
  const rows = []
  for (const location of locations) {
    rows.push({
      path: location.path,
      line: location.line,
      snippet: await ideLineText(store, location.path, location.line, cache),
    })
  }
  return rows
}

/** Java accessor names a property implies: `docId` → `getDocId`, `setDocId`, `isDocId`. */
function ideAccessorNames(name) {
  const base = typeof name === 'string' ? name : ''
  if (base === '') return []
  const capitalized = base.charAt(0).toUpperCase() + base.slice(1)
  return [`get${capitalized}`, `set${capitalized}`, `is${capitalized}`]
}

/** Files one textual caller search may read while checking receivers. */
const IDE_MAX_TEXTUAL_FILES = 12

/** Escape one identifier for a regular expression. */
function ideRegexEscape(text) {
  return String(text ?? '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/** The property an accessor name implies: `getName` → `name`, `isActive` → `active`. */
function ideAccessorProperty(name) {
  const match = /^(?:get|set|is)([A-Z][\w$]*)$/.exec(String(name ?? ''))
  if (match === null) return ''
  return match[1].charAt(0).toLowerCase() + match[1].slice(1)
}

/** Whether one line declares a type named `name` (`public class Name {`). */
function ideIsTypeDeclaration(text, name) {
  if (typeof text !== 'string' || typeof name !== 'string' || name === '') return false
  const pattern = new RegExp(`^\\s*(?:(?:public|protected|private|static|final|abstract|sealed|non-sealed)\\s+)*(?:class|interface|enum|record|@interface)\\s+${ideRegexEscape(name)}\\b`)
  return pattern.test(text)
}

/** Whether one line declares a field named `name` (`private String name;`). */
function ideIsFieldDeclaration(text, name) {
  if (typeof text !== 'string' || typeof name !== 'string' || name === '') return false
  // `return refundNo;` states a type-like token before the name too; only a
  // declaration starts with modifiers/type and nothing else.
  if (/^(?:return|throw|else|if|for|while|switch|case|yield|assert|System)\b/.test(text.trim())) return false
  const pattern = new RegExp(`^\\s*(?:(?:public|protected|private|static|final|transient|volatile)\\s+)*[A-Za-z_$][\\w$<>\\[\\],.?]*\\s+${ideRegexEscape(name)}\\s*[;=]`)
  return pattern.test(text)
}

/**
 * The receiver a call is made on, including a chain broken across lines.
 *
 * `paymentRecordOrderRelationRepository` on the line above and
 * `.listByPaymentTradeNos(...)` on this one is one expression; reading only the
 * current line loses the receiver and the owner of the method with it.
 */
function ideReceiverOfCall(lines, line, character) {
  const text = String((lines ?? [])[line] ?? '')
  const before = text.slice(0, Math.max(0, character))
  if (before.trim() !== '' && !/^\s*\./.test(text)) return ideReceiverToken(before)
  for (let index = line - 1; index >= 0 && index >= line - 16; index -= 1) {
    const previous = String(lines[index] ?? '').trim()
    if (previous === '') continue
    const match = /([A-Za-z_$][\w$]*)\s*$/.exec(previous)
    if (match !== null) return match[1]
    if (!/[.([,]\s*$/.test(previous)) return ''
  }
  return ''
}

/**
 * The dotted expression a call is made on: `PurchaseOrderStatusEnum.TO_PURCHASE`.
 *
 * A single identifier is not enough when the receiver is a static call target or
 * an enum constant — the class that owns the method is the leftmost segment.
 */
function ideReceiverChain(lines, line, character) {
  const text = String((lines ?? [])[line] ?? '')
  const before = text.slice(0, Math.max(0, character)).replace(/\s+$/, '')
  const tail = /[A-Za-z0-9_$.]+$/.exec(before.replace(/\($/, ''))
  const sameLine = tail === null ? '' : tail[0].replace(/\.$/, '')
  if (sameLine !== '' && !/^\s*\./.test(text)) return sameLine
  // A chain broken before the dot: the receiver sits on an earlier line.
  for (let index = line - 1; index >= 0 && index >= line - 16; index -= 1) {
    const previous = String(lines[index] ?? '').trim()
    if (previous === '') continue
    const found = /([A-Za-z0-9_$.]+)\s*$/.exec(previous)
    if (found !== null) return found[1].replace(/\.$/, '')
    if (!/[.([,]\s*$/.test(previous)) return ''
  }
  return ''
}

/** Grep pattern for a declaration of `name`: a type token, then the name. */
function ideDeclarationPattern(name) {
  return `[A-Za-z0-9_$<>\\[\\],.?]+\\s+${ideRegexEscape(name)}\\s*\\(`
}

/** Whether one line declares `name` rather than using it. */
function ideTextualIsDeclaration(text, name) {
  if (typeof text !== 'string' || typeof name !== 'string' || name === '') return false
  const use = new RegExp(`\\b${ideRegexEscape(name)}\\s*\\(`)
  if (!use.test(text)) return false
  const declaration = new RegExp(
    `^\\s*(?:(?:public|protected|private|static|final|abstract|synchronized|default|native)\\s+)*[\\w$<>\\[\\],.?\\s]+\\s+${ideRegexEscape(name)}\\s*\\(`,
  )
  return declaration.test(text)
}

/**
 * Whether one reference row is the method's own declaration.
 *
 * `findReferences` answers with declarations too — the contract's signature
 * line, an override in another class — and those are not call sites.
 */
function ideReferenceIsDeclaration(lines, line, name) {
  const text = String((lines ?? [])[line - 1] ?? '')
  return ideTextualIsDeclaration(text, name)
}

/** Whether one line is a call of `name`, rather than its declaration. */
function ideTextualIsCall(text, name) {
  if (typeof text !== 'string' || typeof name !== 'string' || name === '') return false
  const use = new RegExp(`\\b${ideRegexEscape(name)}\\s*\\(`)
  return use.test(text) && !ideTextualIsDeclaration(text, name)
}

/** Whether one call line invokes `name` through a receiver (`obj.name(`). */
function ideTextualIsReceiverCall(text, name) {
  return new RegExp(`\\.\\s*${ideRegexEscape(name)}\\s*\\(`).test(String(text ?? ''))
}

/**
 * Text fallback for symbols the engine reports no usages for.
 *
 * Two shapes matter:
 *  - a **method**: search its own name at call sites, and for a non-static one
 *    keep only receiver calls (`service.detail(...)`) — a bare `detail(...)` is
 *    usually a different local helper;
 *  - a **field** (Lombok-style property): the field has no accessor in the
 *    sources and references on it answer only its declaration, so its
 *    `getX`/`setX`/`isX` call sites are the closest thing to usages.
 *
 * The popup labels these rows as text matches; they are never presented as
 * semantic references.
 */
async function ideTextualCallers(store, tabPath, position, symbolName, limit, options = {}) {
  if (typeof symbolName !== 'string' || symbolName === '') return []
  const root = store.getState().rootPath
  if (root === '') return []
  const clicked = `${tabPath}:${position.line + 1}`
  // Files are read once each while checking receivers: a name match in a class
  // that holds something else is not a call of this method.
  const fileCache = new Map()
  const linesOf = async (path) => {
    if (fileCache.has(path)) return fileCache.get(path)
    if (fileCache.size >= IDE_MAX_TEXTUAL_FILES) return undefined
    const result = await store.readText(store.getState().sessionId, root, path).catch(() => undefined)
    const lines = result?.ok === true && typeof result.value === 'string' ? result.value.split('\n') : undefined
    fileCache.set(path, lines)
    return lines
  }
  const receiverBelongsTo = async (path, urlLineIndex, text, name) => {
    const lines = await linesOf(path)
    if (lines === undefined) return false
    const line = lines[urlLineIndex] ?? text
    // The first substring may be another identifier (`statisticsResp`); only the
    // occurrence that is followed by `(` is the call.
    const call = new RegExp(`\\b${ideRegexEscape(name)}\\s*\\(`).exec(line)
    if (call === null) return false
    const receiver = ideReceiverChain(lines, urlLineIndex, call.index).split('.')[0]
    if (receiver === '') return false
    const owners = Array.isArray(options.ownerNames) && options.ownerNames.length > 0 ? options.ownerNames : ['']
    const declared = ideDeclaredType(lines, receiver)
    if (owners.includes('') || owners.includes(declared)) return true
    // `ReconBillConverter.toDifferenceResp(…)` keeps the class name as the
    // receiver (a static call, or Lombok's @UtilityClass); the class itself is
    // the owner, so the receiver is one.
    return /^[A-Z]/.test(receiver) && owners.includes(receiver)
  }
  const collect = async (pattern, names, requireReceiver) => {
    const found = await ideGrepQuery(root, pattern, { caseSensitive: true, extensions: IDE_CODE_EXTENSIONS })
    if (found.ok !== true) return []
    const rows = []
    const seen = new Set()
    for (const match of found.matches) {
      const key = `${match.path}:${match.line}`
      if (key === clicked || seen.has(key)) continue
      const text = String(match.text ?? '')
      const name = names.find((candidate) => ideTextualIsCall(text, candidate))
      if (name === undefined) continue
      if (requireReceiver && !ideTextualIsReceiverCall(text, name)) continue
      if (requireReceiver && !(await receiverBelongsTo(match.path, match.line - 1, text, name))) continue
      seen.add(key)
      rows.push({ path: match.path, line: match.line, snippet: match.text })
    }
    return rows
  }

  const exact = await collect(`\\b${ideRegexEscape(symbolName)}\\s*\\(`, [symbolName], options.requireReceiver === true)
  if (exact.length > 0) return exact.slice(0, limit)
  // No call of the symbol itself: a property's accessors are the fallback.
  const accessors = ideAccessorNames(symbolName)
  if (accessors.length === 0) return []
  const byAccessor = await collect(`\\b(?:${accessors.map(ideRegexEscape).join('|')})\\s*\\(`, accessors, false)
  return byAccessor.slice(0, limit)
}

/**
 * Textual implementations of an interface method.
 *
 * Used only when the engine answered nothing: find the classes that implement
 * the clicked file's interface, then the declaration of the method inside them.
 */
async function ideTextualImplementations(store, tabPath, sourceLines, symbolName, limit) {
  const root = store.getState().rootPath
  const className = ideClassName(tabPath)
  if (root === '' || className === '' || typeof symbolName !== 'string' || symbolName === '') return []
  // An interface is extended by implementations; an abstract class by
  // subclasses. Either way the override is what a click on the contract wants.
  const isInterface = sourceLines.some((line) => new RegExp(`\\binterface\\s+${ideRegexEscape(className)}\\b`).test(line))
  const isAbstract = !isInterface && sourceLines.some((line) => new RegExp(`\\babstract\\s+class\\s+${ideRegexEscape(className)}\\b`).test(line))
  if (!isInterface && !isAbstract) return []
  const relation = isInterface ? 'implements' : 'extends'
  const typed = await ideGrepQuery(root, `${relation}[^\\n{]*\\b${ideRegexEscape(className)}\\b`, {
    caseSensitive: true,
    extensions: IDE_CODE_EXTENSIONS,
  })
  if (typed.ok !== true) return []
  const rows = []
  const seen = new Set()
  for (const match of typed.matches) {
    const key = match.path
    if (seen.has(key)) continue
    seen.add(key)
    const declared = await ideGrepQuery(root, `\\b${ideRegexEscape(symbolName)}\\s*\\(`, { path: match.path, caseSensitive: true })
    if (declared.ok !== true) continue
    for (const line of declared.matches) {
      if (!ideTextualIsDeclaration(line.text, symbolName)) continue
      rows.push({ path: line.path, line: line.line, snippet: line.text })
      break
    }
    if (rows.length >= limit) break
  }
  return rows
}

/**
 * Semantic references for a property, anchored at one of its accessor call sites.
 *
 * The engine will not attribute accessor usages to the field itself — asking for
 * references *at the field* answers only its declaration. Asking at a call site
 * of `getX`/`setX`/`isX` does return every usage, semantically. So one text
 * search is used only to find that anchor; the result set is the engine's.
 *
 * @returns locations from the engine, empty when no accessor call exists.
 */
async function ideAccessorReferences(store, tabPath, position, symbolName, timeline) {
  const names = ideAccessorNames(symbolName)
  if (names.length === 0) return []
  const root = store.getState().rootPath
  if (root === '') return []
  const pattern = `\\b(?:${names.join('|')})\\s*\\(`
  const found = await ideGrepQuery(root, pattern, { caseSensitive: true })
  if (found.ok !== true) return []
  const clicked = `${tabPath}:${position.line + 1}`

  // A candidate call site only counts as an anchor when the engine resolves it
  // back to the field that was clicked. Without this check the first `getDocId(`
  // in the workspace wins, which may belong to an unrelated class and returns
  // that symbol's references — visibly wrong results.
  let anchor
  let anchorCharacter = 0
  let tried = 0
  for (const match of found.matches) {
    if (`${match.path}:${match.line}` === clicked) continue
    if (tried >= IDE_MAX_ANCHOR_TRIES) break
    tried += 1
    const name = names.find((candidate) => String(match.text).includes(candidate))
    if (name === undefined) continue
    const character = Math.max(0, String(match.text).indexOf(name))
    const started = ideNow()
    const definition = await ideLspQuery({
      operation: 'goToDefinition',
      filePath: ideAbs(root, match.path),
      workspaceRoot: root,
      position: { line: match.line - 1, character },
    }).catch(() => ({ locations: [] }))
    timeline?.mark('bind', ideNow() - started)
    const located = (definition.locations ?? [])[0]
    if (located === undefined) continue
    if (`${located.path}:${located.line}` !== clicked) continue
    anchor = match
    anchorCharacter = character
    break
  }
  if (anchor === undefined) return []

  const started = ideNow()
  const result = await ideLspQuery({
    operation: 'findReferences',
    filePath: ideAbs(root, anchor.path),
    workspaceRoot: root,
    position: { line: anchor.line - 1, character: anchorCharacter },
  }).catch(() => ({ locations: [] }))
  timeline?.mark('refs', ideNow() - started)
  return result.locations ?? []
}

/** `LSP_SERVER_ERROR — textDocument/references: Method not found (-32601)`. */
function ideLspFailureText(failure) {
  if (failure === undefined || failure === null) return ''
  if (ideLspNeedsLicense(failure) || failure.code === 'LSP_NO_LICENSE') {
    return `license: ${typeof failure.detail === 'string' ? failure.detail : 'no active JetBrains license'}`
  }
  const code = typeof failure.code === 'string' ? failure.code : 'lsp-failed'
  const operation = typeof failure.operation === 'string' ? `${failure.operation}: ` : ''
  const detail = typeof failure.detail === 'string' && failure.detail !== '' ? ` — ${failure.detail}` : ''
  return `${code}${detail === '' ? '' : `${detail}`}${operation === '' ? '' : ` (${operation.replace(/: $/, '')})`}`
}

/** One location's identity, for set arithmetic between queries. */
function ideLocationKey(location) {
  return `${location.path}:${location.line}`
}

/**
 * Everything the popup needs for one symbol: its implementations and its callers.
 *
 * `findReferences` always includes declarations, so they are removed here — the
 * rows this returns are the places that *use* the symbol, while implementations
 * are the places that *fulfil* it. Both lists are deduplicated against the
 * declaration itself, which is where Ctrl/Cmd+click goes instead.
 *
 * @returns `{ implementations, callers }`, each a list of `{ path, line, snippet }`.
 */
async function ideLspBrowse(store, tabPath, position, limits, timeline, onPartial, symbolName) {
  const failures = []
  const run = async (operation, label) => {
    const started = ideNow()
    const result = await ideLspQuery(ideLspPayload(store, operation, tabPath, position))
      .then((value) => value.locations ?? [])
      .catch((error) => {
        // The server states why; the banner is the only place that reason can
        // reach the reader, so keep the first one verbatim.
        failures.push({
          operation,
          code: typeof error?.code === 'string' ? error.code : 'lsp-failed',
          detail: String(error?.detail ?? '').slice(0, 160),
        })
        return []
      })
    timeline?.mark(label, ideNow() - started)
    return result
  }

  // Serialised by the provider, so each query is measured on its own: the point
  // is to publish the first section as soon as it exists instead of holding the
  // whole answer until the slowest query returns.
  const declarations = await run('goToDefinition', 'def')
  const implementations = await run('goToImplementation', 'impl')
  // The clicked line says what kind of symbol this is: a method is followed by
  // `(`, and `static` says whether a bare call may reach it.
  const sourceLines = await store.readLines(tabPath)
  const clickedLine = String(sourceLines[position.line] ?? '')
  // The column points at the symbol itself, so what follows the name says
  // whether this is a method (a `(` next) or a field.
  const afterName = clickedLine.slice(position.character + String(symbolName ?? '').length)
  const isMethod = afterName.trimStart().startsWith('(')
  const isStatic = /\bstatic\b/.test(clickedLine)
  // A caller may hold the interface type while this file is the implementation.
  const ownerNames = [ideClassName(tabPath), ...ideContractNames(sourceLines)].filter((name) => name !== '')

  const declared = new Set(declarations.map(ideLocationKey))
  const implemented = new Set(implementations.map(ideLocationKey))
  const clicked = `${tabPath}:${position.line + 1}`

  const implRows = []
  const seenImpl = new Set()
  for (const location of implementations) {
    const key = ideLocationKey(location)
    if (declared.has(key) || seenImpl.has(key)) continue
    seenImpl.add(key)
    implRows.push(location)
  }

  const partial = {
    implementations: await ideWithSnippets(store, implRows.slice(0, limits.implementations)),
    callers: [],
    declaration: [],
  }
  // First paint: implementations are what a click on a contract is really about.
  if (onPartial !== undefined) onPartial(partial)

  const references = await run('findReferences', 'refs')
  // The popup has the same blind spot as the counter: a caller holding the
  // interface never appears among the implementation's references.
  if (typeof symbolName === 'string' && symbolName !== '') {
    const contract = await ideContractReferences(store, tabPath, sourceLines, symbolName)
    const known = new Set(references.map(ideLocationKey))
    for (const location of contract) {
      const key = ideLocationKey(location)
      if (known.has(key)) continue
      known.add(key)
      references.push(location)
    }
  }

  // Reading the files that own the references lets a declaration that came
  // through the contract merge (the interface's own signature) be dropped: it
  // is the method, not a caller of it.
  const referenceLines = new Map()
  const linesOfReference = async (path) => {
    let pending = referenceLines.get(path)
    if (pending === undefined) {
      pending = Promise.resolve(store.readLines(path)).then((lines) => (Array.isArray(lines) ? lines : [])).catch(() => [])
      referenceLines.set(path, pending)
    }
    return pending
  }
  const callerRows = []
  const seenCaller = new Set()
  for (const location of references) {
    const key = ideLocationKey(location)
    if (key === clicked || declared.has(key) || implemented.has(key) || seenCaller.has(key)) continue
    if (typeof symbolName === 'string' && symbolName !== '' && typeof location?.path === 'string' && typeof location?.line === 'number') {
      const lines = await linesOfReference(location.path)
      if (ideReferenceIsDeclaration(lines, location.line, symbolName)) continue
    }
    seenCaller.add(key)
    callerRows.push(location)
  }

  // A field or an enum constant is often declared and referenced in one place
  // only; when nothing is left after removing the declaration, the declaration
  // itself is still the useful answer.
  const needsDeclaration = implRows.length === 0 && callerRows.length === 0
  const declarationRows = needsDeclaration
    ? declarations.filter((location) => ideLocationKey(location) !== clicked)
    : []

  const callers = await ideWithSnippets(store, callerRows.slice(0, limits.callers))
  if (implRows.length === 0 && callers.length === 0) {
    // The engine answers for the accessor even though it answers nothing for the
    // field, so this branch still produces semantic callers. It only makes sense
    // for a field: `detail` and `getDetail` are different methods.
    const anchored = isMethod ? [] : await ideAccessorReferences(store, tabPath, position, symbolName, timeline)
    const anchoredRows = []
    const seenAnchored = new Set()
    for (const location of anchored) {
      const key = ideLocationKey(location)
      if (key === clicked || seenAnchored.has(key)) continue
      seenAnchored.add(key)
      anchoredRows.push(location)
      if (anchoredRows.length >= limits.callers) break
    }
    if (anchoredRows.length > 0) {
      return {
        implementations: partial.implementations,
        callers: await ideWithSnippets(store, anchoredRows),
        declaration: [],
        textual: [],
      }
    }
    const textual = await ideTextualCallers(store, tabPath, position, symbolName, limits.callers, {
      // A non-static method is reached through a receiver; a bare same-name call
      // is usually a different local helper, and a receiver of another declared
      // type is a different method with the same name.
      requireReceiver: isMethod && !isStatic,
      ownerNames,
    })
    const implementationsText = await ideTextualImplementations(store, tabPath, sourceLines, symbolName, limits.implementations)
    if (textual.length > 0 || implementationsText.length > 0) {
      return {
        implementations: partial.implementations,
        implementationsText,
        callers: [],
        declaration: [],
        textual,
        failed: '',
      }
    }
  }
  return {
    implementations: partial.implementations,
    implementationsText: [],
    callers,
    declaration: await ideWithSnippets(store, declarationRows.slice(0, 1)),
    textual: [],
    // Every query failing is a server problem, not "no usages": the popup must
    // not tell the reader the symbol is unused when nothing answered.
    failed: failures.length === 3 ? ideLspFailureText(failures[0]) : '',
  }
}

/**
 * The identifier the clicked accessor is called on, from the text before it.
 *
 * Handles both `older.` and a chained receiver such as `captor.getValue().`,
 * where the interesting name sits before the closing parenthesis.
 */
function ideReceiverToken(before) {
  const text = String(before ?? '').replace(/\s+$/, '')
  if (!text.endsWith('.')) return ''
  const head = text.slice(0, -1).replace(/\s+$/, '')
  if (head.endsWith(')')) {
    let depth = 0
    for (let index = head.length - 1; index >= 0; index -= 1) {
      if (head[index] === ')') depth += 1
      else if (head[index] === '(') {
        depth -= 1
        if (depth === 0) {
          const name = /([A-Za-z_$][\w$]*)\s*$/.exec(head.slice(0, index))
          return name === null ? '' : name[1]
        }
      }
    }
    return ''
  }
  const name = /([A-Za-z_$][\w$]*)$/.exec(head)
  return name === null ? '' : name[1]
}

/**
 * The declared type of a local variable, from the open file's own source.
 *
 * `ExchangeRateInnerResp older = ...` is enough to know what `older.getX()`
 * returns without asking the engine anything.
 */
function ideDeclaredType(lines, name) {
  // `private final Type field;` is how a controller holds its service; the
  // modifiers must not stop the declaration from being recognised.
  const pattern = new RegExp(`^\\s*(?:(?:public|protected|private|static|final|transient|volatile)\\s+)*([A-Z][\\w$]*(?:<[^;=]*>)?)\\s+${name}\\s*[;=,)]`)
  for (const text of lines) {
    const match = pattern.exec(text)
    if (match !== null) return match[1].replace(/<.*$/, '')
  }
  return ''
}

/**
 * The object a chained call hangs off, e.g. `captor` in `captor.getValue()`.
 *
 * The generic-argument trick needs the *variable*, not the method name: the
 * declaration that states `<ExchangeRateInnerQuery>` declares `captor`.
 */
function ideChainBase(before, methodName) {
  if (methodName === '') return ''
  const pattern = new RegExp(`([A-Za-z_$][\\w$]*)\\s*\\.\\s*${methodName}\\s*\\([^()]*\\)\\s*\\.\\s*$`)
  const match = pattern.exec(String(before ?? ''))
  return match === null ? '' : match[1]
}

/**
 * The first generic type argument of a local declaration, e.g. the `T` in
 * `ArgumentCaptor<T> captor = ...`.
 *
 * A chained receiver such as `captor.getValue().getX()` returns that argument, so
 * this resolves the case without asking the engine.
 */
function ideGenericArgument(lines, name) {
  // The type may be package-qualified (`org.mockito.ArgumentCaptor<T>`), so the
  // leading segments are allowed to be lowercase and the last one must be a type.
  const declaration = new RegExp(`^\\s*(?:final\\s+)?(?:[a-z][\\w$]*\\.)*[A-Z][\\w$]*\\s*<\\s*([A-Z][\\w$]*)\\s*[,>]`)
  const binding = new RegExp(`\\b${name}\\s*[;=,)]`)
  for (const text of lines) {
    if (!binding.test(text)) continue
    const match = declaration.exec(text)
    if (match !== null) return match[1]
  }
  return ''
}

/**
 * Query `hover` and return its text, for resolving a receiver's type.
 *
 * The engine answers a method call with its signature, whose first type name is
 * the value type; a receiver the engine cannot describe yields `''`.
 */
async function ideLspHoverText(store, tabPath, position) {
  let result
  try {
    result = await ideLspQuery(ideLspPayload(store, 'hover', tabPath, position))
  } catch (error) {
    void error
    return ''
  }
  const hover = result?.hover
  if (hover === undefined || hover === null) return ''
  const contents = hover.contents
  if (typeof contents === 'string') return contents
  if (typeof contents?.value === 'string') return contents.value
  if (Array.isArray(contents)) {
    return contents.map((entry) => (typeof entry === 'string' ? entry : entry?.value ?? '')).join('\n')
  }
  return ''
}

// ---- 66-callchain.js -----------------------------------------------------
/*
 * The call chain of one method, as a tree.
 *
 * LSP answers "who references this symbol"; walking that answer upward — and
 * resolving each call site to the method that contains it — is what produces the
 * chain from an entry point down to the clicked method. Every node carries the
 * location of its declaration, so a click in the popup is an ordinary jump.
 */

const IDE_CHAIN_DEPTH = 3
const IDE_CHAIN_NODES = 40
const IDE_CHAIN_CHILDREN = 6

/** The last declaration strictly above `line` (1-based) in one file. */
function ideEnclosingDeclaration(lines, line) {
  const declarations = ideDeclarations(lines, 0, Math.max(0, line - 1))
  return declarations.length === 0 ? undefined : declarations[declarations.length - 1]
}

/** Interface simple names one class declaration implements. */
function ideContractNames(lines) {
  for (const line of lines) {
    const at = line.indexOf('implements')
    if (at < 0 || !/\b(?:class|enum|record)\b/.test(line)) continue
    const tail = line.slice(at + 'implements'.length)
    const cut = tail.indexOf('{')
    return tail.slice(0, cut < 0 ? tail.length : cut)
      .split(',')
      .map((part) => part.trim().split(/[<.\s]/)[0])
      .filter((part) => part !== '')
  }
  return []
}

/** Interface simple name → the workspace files that declare it. */
const ideInterfacePaths = new Map()

/** Resolve one interface's declaration files (a name is unique in a workspace). */
async function ideInterfacePathsOf(root, name) {
  let pending = ideInterfacePaths.get(name)
  if (pending === undefined) {
    pending = ideGrepQuery(root, `\\binterface\\s+${name}\\b`, { extensions: IDE_CODE_EXTENSIONS, caseSensitive: true })
      .then((answer) => (answer.ok === true ? answer.matches : []))
      .catch(() => [])
    ideInterfacePaths.set(name, pending)
  }
  const matches = await pending
  return matches.filter((match) => typeof match?.path === 'string').map((match) => match.path)
}

/**
 * Call sites that reach a method through its contract.
 *
 * A caller holding the interface type (`ReconBillGenerateService service;`)
 * resolves to the interface declaration; the implementation's own references
 * never mention it. Reading the `implements` clause, finding the same method in
 * the interface and asking *there* is what reunites the two halves.
 *
 * @returns `{ path, line }[]`, empty when the class overrides no such method.
 */
async function ideContractReferences(store, path, lines, name) {
  const root = store.getState().rootPath
  if (root === '' || typeof name !== 'string' || name === '') return []
  const contracts = ideContractNames(lines)
  if (contracts.length === 0) return []
  const found = []
  for (const contractName of contracts) {
    for (const contractPath of await ideInterfacePathsOf(root, contractName)) {
      const contractLines = await store.readLines(contractPath)
      const declaration = ideDeclarations(contractLines, 0, contractLines.length)
        .find((entry) => entry.name === name)
      if (declaration === undefined) continue
      const answer = await ideLspQuery({
        operation: 'findReferences',
        filePath: ideAbs(root, contractPath),
        workspaceRoot: root,
        position: { line: declaration.index, character: declaration.column },
      }).catch(() => undefined)
      if (Array.isArray(answer?.locations)) found.push(...answer.locations)
    }
  }
  return found
}

/** Whether a reference line declares a method instead of calling one. */
function ideChainDeclaresAt(lines, line) {
  return ideDeclarations(lines, line - 1, line).length > 0
}

/**
 * Turn the caller tree into the tree the popup shows.
 *
 * The caller tree points down at callers; people read a chain the other way —
 * the entry on top, the clicked method at the bottom, every arrow going
 * "this one calls the one below it". Each entry-to-target path becomes its own
 * branch, so a method reached from two places is drawn twice instead of once.
 */
function ideChainInverted(tree) {
  const parentOf = new Map()
  const leaves = []
  const walk = (node) => {
    if (node.children.length === 0) leaves.push(node)
    for (const child of node.children) {
      parentOf.set(child, node)
      walk(child)
    }
  }
  walk(tree)
  const build = (node) => ({
    name: node.name,
    path: node.path,
    line: node.line,
    callSite: node.callSite,
    focus: node.focus === true,
    children: parentOf.has(node) ? [build(parentOf.get(node))] : [],
  })
  return leaves.map(build)
}

/** How many methods one tree holds. */
function ideChainCount(node) {
  if (node === undefined || node === null) return 0
  return 1 + node.children.reduce((sum, child) => sum + ideChainCount(child), 0)
}

/**
 * Build the caller tree of one method.
 *
 * @param store - the workspace store; it reads the files that are not open.
 * @param root - `{ name, path, line, position }`, the clicked method.
 * @param options.onPartial - called with the tree after each level, so the
 *   popup can paint what is known instead of waiting for the deepest caller.
 * @returns the tree, filled in.
 */
async function ideCallChain(store, root, options = {}) {
  const tree = { ...root, focus: true, children: [] }
  const files = new Map()
  const linesOf = (path) => {
    let pending = files.get(path)
    if (pending === undefined) {
      pending = Promise.resolve(store.readLines(path)).then((lines) => (Array.isArray(lines) ? lines : []))
      files.set(path, pending)
    }
    return pending
  }
  /**
   * The method containing a call site, or nothing when it sits outside one.
   *
   * `findReferences` also answers with the symbol's own declaration (and, for a
   * contract, the declarations of its overrides). Those lines declare a method
   * instead of calling one, so they are not call sites and must not become a
   * caller — reading one as "the previous method calls it" is what made every
   * arrow point at the parent's own signature line.
   */
  const callerAt = async (path, line) => {
    const lines = await linesOf(path)
    if (ideChainDeclaresAt(lines, line)) return 'declaration'
    const declaration = ideEnclosingDeclaration(lines, line)
    if (declaration === undefined) return undefined
    return {
      name: declaration.name,
      line: declaration.index + 1,
      position: { line: declaration.index, character: declaration.column },
    }
  }

  // The engine may be down (or its project model incomplete). A chain that
  // silently answers "no callers" in that state is worse than a text-matched
  // one, so a level with no semantic references falls back to the same
  // receiver-checked text search the usages popup uses.
  let textual = false
  let failure = ''
  const textualCallersOf = async (node) => {
    const lines = await linesOf(node.path)
    const lineText = String(lines[node.position.line] ?? '')
    const afterName = lineText.slice(node.position.character + String(node.name ?? '').length)
    if (!afterName.trimStart().startsWith('(')) return []
    const ownerNames = [ideClassName(node.path), ...ideContractNames(lines)].filter((name) => name !== '')
    const rows = await ideTextualCallers(store, node.path, node.position, node.name, IDE_CHAIN_CHILDREN, {
      requireReceiver: !/\bstatic\b/.test(lineText),
      ownerNames,
    }).catch(() => [])
    if (rows.length === 0) return []
    textual = true
    return rows.map((row) => ({ path: row.path, line: row.line }))
  }

  const seen = new Set([`${root.path}:${root.line}`])
  let level = [tree]
  let count = 1
  for (let depth = 1; depth <= IDE_CHAIN_DEPTH && level.length > 0; depth += 1) {
    const next = []
    for (const node of level) {
      const [answer, contract] = await Promise.all([
        ideLspQuery(ideLspPayload(store, 'findReferences', node.path, node.position)).catch((error) => {
          if (failure === '') {
            failure = ideLspFailureText({
              operation: 'findReferences',
              code: typeof error?.code === 'string' ? error.code : 'lsp-failed',
              detail: String(error?.detail ?? '').slice(0, 160),
            })
          }
          return undefined
        }),
        ideContractReferences(store, node.path, await linesOf(node.path), node.name),
      ])
      const semantic = [...(Array.isArray(answer?.locations) ? answer.locations : []), ...contract]
      const locations = semantic.length > 0 ? semantic : await textualCallersOf(node)
      let added = 0
      for (const location of locations) {
        if (count >= IDE_CHAIN_NODES || added >= IDE_CHAIN_CHILDREN) break
        if (typeof location?.path !== 'string' || typeof location?.line !== 'number') continue
        // The declaration of the method we are walking is not a call to it.
        if (location.path === node.path && location.line === node.line) continue
        const caller = await callerAt(location.path, location.line)
        if (caller === 'declaration') continue
        // A call site outside any method (a field initialiser, a static block):
        // the line itself is the node, so the chain never loses that caller.
        const target = caller ?? {
          name: ideBasename(location.path),
          line: location.line,
          position: { line: location.line - 1, character: 0 },
        }
        const key = `${location.path}:${target.line}`
        if (seen.has(key)) continue
        seen.add(key)
        count += 1
        added += 1
        const child = {
          ...target,
          path: location.path,
          callSite: { path: location.path, line: location.line },
          children: [],
        }
        node.children.push(child)
        next.push(child)
      }
    }
    level = next
    options.onPartial?.(tree)
  }
  tree.textual = textual
  tree.failed = textual ? '' : failure
  return tree
}

/** `ReconBillQueryServiceImpl:339` — the file without its directory or extension. */
function ideChainFileOf(path) {
  const name = ideBasename(path)
  return name.endsWith('.java') ? name.slice(0, -'.java'.length) : name
}

/** One node card plus its children, joined by rounded elbows. */
function IdeChainNode({ node, depth, onPick }) {
  const where = `${ideChainFileOf(node.path)}:${node.line}`
  return h('div', { className: 'iw-chain-node' }, [
    h('button', {
      key: 'row',
      type: 'button',
      className: `iw-chain-row${node.focus === true ? ' root' : ''}`,
      title: `${node.path}:${node.line}`,
      onClick: () => onPick(node.path, node.line),
    }, [
      h('span', { key: 'dot', className: 'iw-chain-dot' }),
      h('span', { key: 'n', className: 'iw-chain-name' }, node.name),
      h('span', { key: 'p', className: 'iw-chain-where' }, where),
      node.callSite === undefined
        ? null
        : h('span', { key: 's', className: 'iw-chain-site', title: `${node.callSite.path}:${node.callSite.line}` }, `← :${node.callSite.line}`),
    ]),
    node.children.length === 0
      ? null
      : h('div', { key: 'children', className: 'iw-chain-children' }, node.children.map((child) => h(IdeChainNode, {
        key: `${child.path}:${child.line}`,
        node: child,
        depth: depth + 1,
        onPick,
      }))),
  ])
}

/** The popup: one tree, one row per method; clicking a row jumps to it. */
function IdeChainPopup({ popup, tr, onPick, onClose }) {
  const ref = React.useRef(null)
  // The popup owns the keyboard while it is open: capture-phase, so no other
  // handler has to be focused for Esc to close it.
  useEffect(() => {
    if (ref.current !== null && typeof ref.current.focus === 'function') ref.current.focus()
  }, [])
  useEffect(() => {
    const onDown = (event) => {
      const element = event.target
      if (element instanceof Element && element.closest('.iw-pop') !== null) return
      onClose()
    }
    const onKey = (event) => {
      if (event.key !== 'Escape') return
      event.preventDefault()
      event.stopPropagation()
      onClose()
    }
    globalThis.addEventListener('pointerdown', onDown, true)
    globalThis.addEventListener('keydown', onKey, true)
    return () => {
      globalThis.removeEventListener('pointerdown', onDown, true)
      globalThis.removeEventListener('keydown', onKey, true)
    }
  }, [onClose])

  const root = popup.tree
  const count = ideChainCount(root)
  const status = popup.state === 'loading'
    ? tr('chainLoading')
    : `${count}${typeof popup.ms === 'number' ? ` · ${popup.ms}ms` : ''}`
  const forest = root === undefined ? [] : ideChainInverted(root)
  const note = root === undefined
    ? ''
    : (typeof root.failed === 'string' && root.failed.startsWith('license:')
      ? tr('lspLicense')
      : (root.textual === true ? tr('chainTextual') : (root.failed ? tr('chainTextual') : '')))
  const body = h(React.Fragment, null, [
    h('div', { key: 'rule', className: 'iw-chain-rule' }, tr('chainRule')),
    note === '' ? null : h('div', { key: 'note', className: 'iw-chain-note' }, note),
    root === undefined || (count <= 1 && popup.state === 'ready')
      ? h('div', { key: 'empty', className: 'iw-hint' }, popup.empty ?? tr('chainNone'))
      : h('div', { key: 'forest', className: 'iw-chain-roots' }, forest.map((entry, index) => h(IdeChainNode, {
        key: `${entry.path}:${entry.line}:${index}`,
        node: entry,
        depth: 0,
        onPick,
      }))),
  ])
  return h('div', {
    ref,
    tabIndex: -1,
    className: 'iw-pop iw-pop-chain',
    style: { left: `${popup.x}px`, top: `${popup.y}px` },
    role: 'dialog',
    'aria-label': popup.name,
  }, [
    h('div', { key: 'head', className: 'iw-pop-head' }, [
      h('span', { key: 'n', className: 'iw-pop-name' }, popup.name),
      h('span', { key: 'c', className: 'iw-pop-count', title: tr('chainHint') }, status),
    ]),
    h('div', { key: 'body', className: 'iw-pop-body' }, body),
  ])
}

// ---- 68-grep.js ----------------------------------------------------------
/**
 * Content search, through this plugin's own Host route.
 *
 * DSH exposes no content-search service to Client halves, so the Host half runs
 * the ripgrep binary the app already ships and returns `{ path, line, text }`
 * rows. That keeps "search everything" honest: the text tab shows real matches
 * with their line numbers, not an approximation.
 */

/** The grep route, resolved against the page base so proxy prefixes survive. */
function ideGrepUrl() {
  const base = typeof document !== 'undefined' && typeof document.baseURI === 'string'
    ? document.baseURI
    : 'http://dsh.internal/'
  return new URL('dsh-ide/grep', base).href
}

/**
 * Ask the Host for content matches.
 *
 * @param options - optional `path` (one file or directory inside the
 *   workspace), `caseSensitive`, and `extensions` (source suffixes; the Host
 *   turns them into ripgrep include globs).
 * @returns `{ ok: true, matches, truncated }` or `{ ok: false, error }`.
 */
async function ideGrepQuery(root, query, options = {}) {
  const { path: scope, caseSensitive, extensions, signal } = options
  let response
  try {
    response = await fetch(ideGrepUrl(), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        query,
        workspaceRoot: root,
        ...scope === undefined || scope === '' ? {} : { path: scope },
        ...caseSensitive === true ? { caseSensitive: true } : {},
        ...Array.isArray(extensions) && extensions.length > 0 ? { extensions } : {},
      }),
      signal,
    })
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') throw error
    return { ok: false, error: 'network' }
  }
  const parsed = await response.json().catch(() => null)
  if (parsed === null) return { ok: false, error: `http-${response.status}` }
  if (parsed.ok !== true) return { ok: false, error: parsed.error?.code ?? 'grep-failed' }
  return {
    ok: true,
    matches: Array.isArray(parsed.value?.matches) ? parsed.value.matches : [],
    truncated: parsed.value?.truncated === true,
  }
}

